#!/bin/sh
set -eu
cd tests/corpus
"${MAGO_BIN:-../../vendor/bin/mago}" analyze --reporting-format json --minimum-report-level note > /tmp/mago-doctrine-query-budget-report.json || test "$?" -eq 1
php -r '$r=json_decode(file_get_contents("/tmp/mago-doctrine-query-budget-report.json"),true,512,JSON_THROW_ON_ERROR); $found=[]; foreach($r["issues"] as $i){ $found[$i["code"]][]=$i; } foreach(["query-budget-exceeded","recursive-call","query-budget-incomplete"] as $code){ if(empty($found["byte-kitsune/doctrine-query-budget/".$code])) exit(1); } $budget=$found["byte-kitsune/doctrine-query-budget/query-budget-exceeded"][0]; $note=$budget["notes"][0]??""; $data=json_decode(substr($note,strlen("query-budget-evidence: ")),true,512,JSON_THROW_ON_ERROR); if($data["lower_bound"]!==4 || $data["upper_bound"]!==4) exit(1); $orm=array_values(array_filter($found["byte-kitsune/doctrine-query-budget/query-budget-incomplete"],fn($i)=>str_contains($i["message"],"OrmController::index")))[0]??null; if($orm===null) exit(1); $data=json_decode(substr($orm["notes"][0],strlen("query-budget-evidence: ")),true,512,JSON_THROW_ON_ERROR); if($data["lower_bound"]!==0 || $data["upper_bound"]!==null) exit(1); $markers=$found["byte-kitsune/doctrine-query-budget/analysis-attestation"]??[]; if(count($markers)!==1) exit(1); $note=$markers[0]["notes"][0]??""; if(!str_starts_with($note,"extension-attestation: ")) exit(1); $attestation=json_decode(substr($note,strlen("extension-attestation: ")),true,512,JSON_THROW_ON_ERROR); if(($attestation["extension"]??null)!=="byte-kitsune/doctrine-query-budget" || ($attestation["version"]??null)!=="0.1.0-beta.7" || ($attestation["capability"]??null)!=="query_budget" || ($attestation["complete"]??null)!==true || ($attestation["source_files"]??0)<1) exit(1); echo "Mago query-budget corpus passed\n";'
php ../assert-function-report.php
php ../assert-try-report.php
